    describe('glue code tests', () => {
        test('Convert BusinessRule with glue code to module with params', async () => {
            const project = ctx.createProject()
            project.addFile({
                content: `export function myGlueCode(current, previous, g_scratchpad) {
    g_scratchpad.my_string = 'hello world';
}`,
                path: 'src/server/my-glue-code.js',
            })
            const sourceFile = project.addFile({
                content: `import { BusinessRule } from '@servicenow/sdk/core'
import { myGlueCode } from '../server/my-glue-code.js'
BusinessRule({
    $id: Now.ID['br_id'],
    name: 'TestBR',
    table: 'incident',
    message: '<p>Cool Message Right</p>',
    condition: 'valid_condition',
    filterCondition: 'filter_condition',
    description: 'cool description',
    script: myGlueCode,
    action: ['update', 'delete', 'insert'],
    setFieldValue: 'sec_create=false^EQ',
    roleConditions: ['admin'],
    addMessage: true,
    when: 'before'
})
                `,
                path: 'src/fluent/br.now.ts',
            })

            const result = await sourceFile.getOutput()
            expect(result).toHaveLength(1)

            const { content } = result.find((f) => f.path.endsWith('.xml'))
            expect(content).toBeDefined()

            expect(content.includes('myGlueCode(current, previous, g_scratchpad)')).toBeTruthy()
        })

        test('Convert ACL with glue code to module with current default param', async () => {
            const project = ctx.createProject()
            project.addFile({
                content: `export function myGlueCode(): string {
    return "hello world";
}`,
                path: 'src/server/my-glue-code.js',
            })
            const sourceFile = project.addFile({
                content: `import { BusinessRule } from '@servicenow/sdk/core'
import { myGlueCode } from '../server/my-glue-code.js'
BusinessRule({
    $id: Now.ID['br_id'],
    name: 'TestBR',
    table: 'incident',
    message: '<p>Cool Message Right</p>',
    condition: 'valid_condition',
    filterCondition: 'filter_condition',
    description: 'cool description',
    script: myGlueCode,
    action: ['update', 'delete', 'insert'],
    setFieldValue: 'sec_create=false^EQ',
    roleConditions: ['admin'],
    addMessage: true,
    when: 'before'
})`,
                path: 'src/fluent/br.now.ts',
            })

            const result = await sourceFile.getOutput()
            expect(result).toHaveLength(1)

            const { content } = result.find((f) => f.path.endsWith('.xml'))
            expect(content).toBeDefined()

            //Should default to current, previous
            expect(content.includes('myGlueCode(current, previous)')).toBeTruthy()
        })

        test('Can convert VariableDeclaration-style module arrow functions', async () => {
            const project = ctx.createProject()
            const brId = project.registerExplicitId('sys_script', 'br_id')
            project.addFile({
                content: `export const myGlueCode = (current, previous, g_scratchpad) => {
    g_scratchpad.my_string = 'Hello World!';
}`,
                path: 'src/server/my-glue-code.js',
            })
            const sourceFile = project.addFile({
                content: `import { BusinessRule } from '@servicenow/sdk/core'
import { myGlueCode } from '../server/my-glue-code.js'
BusinessRule({
    $id: Now.ID['br_id'],
    name: 'TestBR',
    table: 'incident',
    message: '<p>Cool Message Right</p>',
    condition: 'valid_condition',
    filterCondition: 'filter_condition',
    description: 'cool description',
    script: myGlueCode,
    action: ['update', 'delete', 'insert'],
    setFieldValue: 'sec_create=false^EQ',
    roleConditions: ['admin'],
    addMessage: true,
    when: 'before'
})`,
                path: 'src/fluent/br.now.ts',
            })

            const diagnostics = (await sourceFile.getDiagnostics()).map((d) => d.message)
            expect(diagnostics).toEqual([])

            const script = (await sourceFile.getRecords()).get('sys_script', brId).get('script').getValue()

            expect(script).toContain('myGlueCode(current, previous, g_scratchpad)')
        })

        test('handles ]]> in script CDATA properly', async () => {
            const project = ctx.createProject({
                config: { fluentDir: 'create/fluent', serverModulesDir: 'create/server' },
            })
            project.registerExplicitId('sys_script', 'br_cdata_test')

            const file = project.addFile({
                path: 'create/fluent/br-cdata.now.ts',
                content: `import { BusinessRule } from '@servicenow/sdk/core'

BusinessRule({
    $id: Now.ID['br_cdata_test'],
    name: 'CDATA Test BR',
    table: 'incident',
    script: 'gs.info("Business rule with ]]> sequence ]]>");',
    when: 'before',
    action: ['insert', 'update']
})`,
            })

            const output = await file.getOutput()
            expect(output).toHaveLength(1)

            // Verify that ]]> is properly escaped in CDATA section
            expect(output[0].content).toContain(
                '<script><![CDATA[gs.info("Business rule with ]]]]><![CDATA[> sequence ]]]]><![CDATA[>");]]></script>'
            )
        })
    })
